{
  "facts": [
    {
      "topic": "target_route",
      "statement": "The old entry resets and configures a compression context, then calls ZSTD_compressStream2 with continue, flush, and end directives.",
      "evidence": [
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 59,
          "end_line": 67,
          "role": "dependency",
          "dependency_reason": "Identifies the target's context setup and parameter helper."
        },
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 69,
          "end_line": 135,
          "role": "dependency",
          "dependency_reason": "Shows the streaming calls, directives, frame resets, and error checks."
        }
      ],
      "absence_claim": false
   ,
      "audited_unit_ids": []
    },
    {
      "topic": "trigger",
      "statement": "The parameter helper requests a strategy from ZSTD_STRATEGY_MIN through ZSTD_STRATEGY_MAX, adjusts the compression parameters, and sets the resulting strategy on the context.",
      "evidence": [
        {
          "unit_id": "u-194debf8ea4cd55b47ba",
          "start_line": 44,
          "end_line": 57,
          "role": "dependency",
          "dependency_reason": "Shows strategy selection and adjustment in the old harness helper."
        },
        {
          "unit_id": "u-194debf8ea4cd55b47ba",
          "start_line": 101,
          "end_line": 110,
          "role": "dependency",
          "dependency_reason": "Shows the adjusted strategy passed to ZSTD_CCtx_setParameter."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "contract",
      "statement": "Before the change, ZSTD_selectBlockCompressor maps valid strategies and dictionary modes to block compressor functions, selects a row based function when applicable, and asserts that the selected function is nonnull.",
      "evidence": [
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 2987,
          "end_line": 3061,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "Before the change, stream initialization derives compression parameters from the requested context parameters; ZSTD_getCParamsFromCCtxParams passes them through ZSTD_adjustCParams_internal.",
      "evidence": [
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 1582,
          "end_line": 1594,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 6122,
          "end_line": 6129,
          "role": "dependency",
          "dependency_reason": "Connects streaming initialization to parameter derivation."
        },
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 6213,
          "end_line": 6235,
          "role": "dependency",
          "dependency_reason": "Shows ZSTD_compressStream2 entering transparent initialization."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "Before the change, ordinary sequence building calls the selected block compressor with the applied strategy. When an external sequence producer fails and fallback is enabled, fallback also calls the selected compressor.",
      "evidence": [
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 3277,
          "end_line": 3299,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 2990,
          "end_line": 2992,
          "role": "dependency",
          "dependency_reason": "Identifies the selector and its dispatch table."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "A successful external sequence producer is an alternate sequence generation route: the old source copies its sequences and returns before selecting an internal block compressor. The old harness helper can register a sequence producer or clear it.",
      "evidence": [
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 3233,
          "end_line": 3274,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-194debf8ea4cd55b47ba",
          "start_line": 77,
          "end_line": 99,
          "role": "dependency",
          "dependency_reason": "Shows producer registration and fallback setup."
        },
        {
          "unit_id": "u-194debf8ea4cd55b47ba",
          "start_line": 156,
          "end_line": 164,
          "role": "dependency",
          "dependency_reason": "Shows the harness helper's conditional producer registration and clearing."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "Before the change, sufficiently small source blocks return without attempting block compression, so selecting a strategy alone does not establish that dispatch is reached on every input.",
      "evidence": [
        {
          "unit_id": "u-860860e3395d8f95d959",
          "start_line": 3146,
          "end_line": 3163,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "consequence",
      "statement": "The old harness checks each streaming compression return for a ZSTD error, then checks decompression success, regenerated size, and equality with the original input.",
      "evidence": [
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 81,
          "end_line": 135,
          "role": "dependency",
          "dependency_reason": "Shows existing compression error checks."
        },
        {
          "unit_id": "u-9dc9e88ae722c8cbe085",
          "start_line": 185,
          "end_line": 205,
          "role": "dependency",
          "dependency_reason": "Shows existing decompression and round trip assertions."
        },
        {
          "unit_id": "u-a7cd9e43defd8d40468a",
          "start_line": 40,
          "end_line": 47,
          "role": "dependency",
          "dependency_reason": "Defines the assertion and ZSTD error checking macros."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "The supplied build script changes to tests/fuzz and delegates fuzzer compilation to ./fuzz.py build all. These lines do not determine the effective compressor exclusion settings.",
      "evidence": [
        {
          "unit_id": "u-043cf5aa9ced10a35cb6",
          "start_line": 19,
          "end_line": 24,
          "role": "dependency",
          "dependency_reason": "Identifies the delegated build step whose settings are needed."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    }
  ],
  "missing_information": [
    "Supplied after version of lib/compress/zstd_compress.c at ZSTD_adjustCParams_internal and ZSTD_selectBlockCompressor, to establish the changed contract and dispatch behavior.",
    "Effective stream_round_trip build path and compressor exclusion settings through tests/fuzz/fuzz.py, tests/fuzz/Makefile, and lib/libzstd.mk.",
    "FUZZ_dataProducer_uint32Range implementation and the ZSTD_STRATEGY_MIN and ZSTD_STRATEGY_MAX definitions, if a concrete finite strategy witness is required."
  ],
  "requested_symbols": [
    "ZSTD_adjustCParams_internal",
    "ZSTD_selectBlockCompressor",
    "FUZZ_dataProducer_uint32Range",
    "ZSTD_STRATEGY_MIN",
    "ZSTD_STRATEGY_MAX"
  ],
  "requested_paths": [
    "lib/compress/zstd_compress.c",
    "lib/libzstd.mk",
    "tests/fuzz/fuzz.py",
    "tests/fuzz/Makefile",
    "tests/fuzz/fuzz_data_producer.c"
  ]
}
